import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.21/x-thread-en.md","filePath":"announcements/v1.21/x-thread-en.md"}'),i={name:"announcements/v1.21/x-thread-en.md"};function c(n,e,d,s,h,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<p>1/ kiwa v1.21 is out — Auth 深化 milestone. After v1.20&#39;s Streaming 深化 (Kafka + Redpanda + NATS in one unified mock), v1.21 lands <strong>the 2026 web-auth main stage</strong> every SaaS team is now migrating to: WebAuthn L3 (Chrome Virtual Authenticator-shaped credential store) + Passkey (platform + roaming + sync fabric) + OAuth 2.1 (RFC 9700 + PKCE mandatory + DPoP sender-constrained token) + OIDC (id_token verify + Discovery + Dynamic Client Registration + Federation). Four new protocol adapters bolted onto <code>@kiwa-lab/auth</code>, zero browsers, zero real Keycloak / Auth0 tenants.</p><p>2/ <code>@kiwa-lab/auth</code> v0.4.0 — 4 protocol unified testing mock. <code>createWebAuthnEnv()</code> returns a Virtual Authenticator-shaped credential store + <code>navigator.credentials</code> mock covering <code>create()</code> (attestation <code>none</code> / <code>packed</code> / <code>fido-u2f</code>, authenticator selection criteria <code>userVerification</code> / <code>residentKey</code> / <code>authenticatorAttachment</code>) + <code>get()</code> (assertion + sign counter monotonicity + user-verified flag). <code>createPasskeyEnv()</code> layers platform vs roaming boundaries + <code>credProps.rk</code> + sync fabric mock (iCloud Keychain / Google Password Manager). 21 WebAuthn tests + 33 Passkey tests.</p><p>3/ OAuth 2.1 (RFC 9700) — <code>createOAuth21Env()</code> gives a mock Authorization Server + Resource Server pair — PKCE S256 code_verifier / code_challenge (RFC 7636, mandatory), DPoP proof JWT header + payload verify (RFC 9449 sender-constrained token, <code>htu</code> / <code>htm</code> / <code>jti</code> / <code>iat</code> binding, 60s clock-skew window), refresh token rotation with reuse detection (leaked-token detection cascades revocation to the whole refresh chain), revocation endpoint (RFC 7009 cascade to derived access + refresh tokens). 45 tests. <code>plain</code> code_challenge_method + <code>implicit</code> grant + <code>password</code> grant all reject with <code>unsupported_response_type</code> — the RFC 9700 hard gates.</p><p>4/ OIDC — <code>createOIDCEnv()</code> provides Discovery (<code>/.well-known/openid-configuration</code>), Dynamic Client Registration (RFC 7591 with <code>none</code> / <code>client_secret_basic</code> / <code>client_secret_post</code> / <code>private_key_jwt</code> auth methods + software_statement JWS), JWKS endpoint + rotation (<code>kid</code> header + <code>jose</code> verify wrapper — old token verifies during grace, new token verifies against rotated key), id_token verify (iss / aud / exp / iat / nonce / at_hash / c_hash + RS256 + ES256 signature), Federation trust chain (OIDC Federation 1.0 draft — trust anchor + intermediate + statement chain verify). 35 tests.</p><p>5/ dogfood apps — <code>dogfood-webauthn-passkey-app</code> (Next.js 15 App Router, /register attestation + /signin assertion + /manage residentKey=required, drives Chrome Virtual Authenticator via <code>page.context().addVirtualAuthenticator</code>, 4 pattern fidelity: userVerification × residentKey × authenticatorAttachment × sync fabric) + <code>dogfood-oauth21-provider</code> (Hono + Cloudflare Workers custom AS, 5 endpoint: /authorize + /token + /revoke + /userinfo + /.well-known/oauth-authorization-server, real driver = oauth2-mock-server, 4 pattern fidelity: PKCE S256 + DPoP proof + refresh rotation + revocation cascade) + <code>dogfood-oidc-federation</code> (Nuxt 3 RP + Deno custom OP, Discovery + DCR + JWKS rotation + id_token verify + Federation trust chain, real driver = mock Keycloak-shaped OP, 4 pattern fidelity: Discovery + DCR + JWKS rotation + Federation). All 3 hit 7-axis release gate PASS.</p><p>6/ Testing-hard-parts SSOT (concept doc <code>auth-protocol-testing.md</code>) — 4 protocol × 4 hard-parts SSOT: Virtual Authenticator (Chrome CDP <code>WebAuthn.addVirtualAuthenticator</code> vs <code>@kiwa-lab/auth</code> mock — same credential store shape, same sign counter monotonicity guarantees) / PKCE + DPoP (S256 base64url no-padding + SHA-256 digest / DPoP <code>htu</code> normalizer + <code>htm</code> case-insensitive + <code>jti</code> replay-detection window + <code>iat</code> clock-skew tolerance) / id_token verify (JOSE-compatible RS256 + ES256 verify + full-claim verify with clock skew + <code>at_hash</code> / <code>c_hash</code> covariance with hash-algo derived from <code>alg</code>) / Discovery + Federation (well-known cache-control respect + JWKS rotation with kid rollover + Federation statement chain intermediate substitution attack detection).</p><p>7/ 1 npm minor bump — <code>@kiwa-lab/auth</code> v0.3.0 → v0.4.0 published to npm. kiwa runtime fixture stays at 34 packages (auth is an existing package extension). docs: 3 tutorials (34 WebAuthn + Passkey + 35 OAuth 2.1 provider + 36 OIDC + Federation) + additive migration v1.20 → v1.21 + concept doc <code>auth-protocol-testing.md</code> (4 protocol × 4 testing hard-parts SSOT). VitePress + gh-pages published. Roadmap: <a href="https://github.com/cardene777/kiwa#roadmap" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa#roadmap</a> — v1.11 → v1.12 → v1.13 → v1.14 → v1.15 → v1.16 → v1.17 → v1.18 → v1.19 → v1.20 → v1.21: 11 milestones in a row.</p>',7)])])}const v=o(i,[["render",c]]);export{u as __pageData,v as default};
